class Solution:
    def numberOfBoomerangs(self, points: List[List[int]]) -> int:
        n = len(points)
        ans = 0
        for i in range(n):
            for j in range(n):
                if j == i:
                    continue
                dx1, dy1 = points[i][0] - points[j][0], points[i][1] - points[j][1]
                d1 = dx1 * dx1 + dy1 * dy1
                for k in range(n):
                    if k == i or k == j:
                        continue
                    dx2, dy2 = points[i][0] - points[k][0], points[i][1] - points[k][1]
                    if d1 == dx2 * dx2 + dy2 * dy2:
                        ans += 1
        return ans

