class Solution {
public:
    int numberOfBoomerangs(vector<vector<int>>& points) {
        int n = points.size(), ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (j == i) continue;
                long long dx = points[i][0] - points[j][0];
                long long dy = points[i][1] - points[j][1];
                long long d1 = dx * dx + dy * dy;
                for (int k = 0; k < n; k++) {
                    if (k == i || k == j) continue;
                    long long ex = points[i][0] - points[k][0];
                    long long ey = points[i][1] - points[k][1];
                    if (d1 == ex * ex + ey * ey) ans++;
                }
            }
        }
        return ans;
    }
};

