        ans = 0
        for x1, y1 in points:
            dist_count = defaultdict(int)
            for x2, y2 in points:
                d = (x1 - x2) ** 2 + (y1 - y2) ** 2
                dist_count[d] += 1
            for c in dist_count.values():
                ans += c * (c - 1)
        return ans

