class Solution {
public:
    int numberOfBoomerangs(vector<vector<int>>& points) {
        int ans = 0;
        unordered_map<long long, int> cnt;
        for (auto& p : points) {
            cnt.clear();
            for (auto& q : points) {
                long long dx = p[0] - q[0], dy = p[1] - q[1];
                cnt[dx * dx + dy * dy]++;
            }
            for (auto& [d, c] : cnt) ans += c * (c - 1);
        }
        return ans;
    }
};

