class Solution {
    public int numberOfBoomerangs(int[][] points) {
        int ans = 0;
        Map<Long, Integer> cnt = new HashMap<>();
        for (int[] p : points) {
            cnt.clear();
            for (int[] q : points) {
                long dx = p[0] - q[0], dy = p[1] - q[1];
                cnt.merge(dx * dx + dy * dy, 1, Integer::sum);
            }
            for (int c : cnt.values()) ans += c * (c - 1);
        }
        return ans;
    }
}

